class Solution {
    public int calculate(String s) {
        Deque<Integer> stack = new ArrayDeque<>();
        int num = 0;
        char prevOp = '+';

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            if (Character.isDigit(c)) {
                num = num * 10 + (c - '0');
            }

            // 遇到运算符或到达末尾时，处理之前的数字
            if ((!Character.isDigit(c) && c != ' ') || i == s.length() - 1) {
                switch (prevOp) {
                    case '+' -> stack.push(num);
                    case '-' -> stack.push(-num);
                    case '*' -> stack.push(stack.pop() * num);
                    case '/' -> stack.push(stack.pop() / num);
                }
                prevOp = c;
                num = 0;
            }
        }

        int result = 0;
        while (!stack.isEmpty()) {
            result += stack.pop();
        }

        return result;
    }
}

class Solution {
    public int calculate(String s) {
        int result = 0;
        int lastNum = 0;
        int num = 0;
        char prevOp = '+';

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            if (Character.isDigit(c)) {
                num = num * 10 + (c - '0');
            }

            if ((!Character.isDigit(c) && c != ' ') || i == s.length() - 1) {
                if (prevOp == '+') {
                    result += lastNum;
                    lastNum = num;
                } else if (prevOp == '-') {
                    result += lastNum;
                    lastNum = -num;
                } else if (prevOp == '*') {
                    lastNum = lastNum * num;
                } else if (prevOp == '/') {
                    lastNum = lastNum / num;
                }
                prevOp = c;
                num = 0;
            }
        }

        return result + lastNum;
    }
}
